class Solution {
public:
    vector<int> fullBloomFlowers(vector<vector<int>>& flowers, vector<int>& people) {
        int n = (int)flowers.size();
        vector<int> starts(n), ends(n);
        for (int i = 0; i < n; i++) {
            starts[i] = flowers[i][0];
            ends[i]   = flowers[i][1];
        }
        sort(starts.begin(), starts.end());
        sort(ends.begin(),   ends.end());

        vector<int> ans;
        ans.reserve(people.size());
        for (int t : people) {
            int started = (int)(upper_bound(starts.begin(), starts.end(), t) - starts.begin());
            int ended   = (int)(lower_bound(ends.begin(),   ends.end(),   t) - ends.begin());
            ans.push_back(started - ended);
        }
        return ans;
    }
};
